namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0
        ? Math.Round((double)TotalRatingPoints / RatingCount, 1)
        : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class RecipeFormModel
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "A short description is required.")]
    [StringLength(300, ErrorMessage = "Description must be 300 characters or fewer.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "Add at least one ingredient.")]
    [MinLength(1, ErrorMessage = "Add at least one ingredient.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Add at least one step.")]
    [MinLength(1, ErrorMessage = "Add at least one step.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;
    private int _nextId;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right with hearty morning meals", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals that are quick and satisfying", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Comforting evening dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and indulgent finales", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites for any time of day", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Refreshing beverages and cocktails", Icon = "🥤" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "2 tbsp sugar", "1 tsp baking powder", "Pinch of salt", "Butter for cooking"],
                Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs and milk together, then combine with dry mix.", "Heat a buttered pan over medium heat.", "Pour ¼ cup batter per pancake.", "Flip when bubbles form on the surface.", "Serve with maple syrup and fresh berries."],
                TotalRatingPoints = 23, RatingCount = 5
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple, delicious, and endlessly customizable avocado toast.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Lemon juice", "Red pepper flakes", "Salt and pepper", "Optional: poached egg"],
                Steps = ["Toast the bread until golden and crisp.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread avocado onto toast.", "Top with red pepper flakes and optional poached egg."],
                TotalRatingPoints = 18, RatingCount = 4
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Description = "A crisp and tangy classic Caesar salad with homemade dressing.",
                Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "Caesar dressing", "Lemon wedge"],
                Steps = ["Wash and chop romaine lettuce.", "Toss with Caesar dressing.", "Add croutons and shaved parmesan.", "Squeeze lemon over top and serve."],
                TotalRatingPoints = 13, RatingCount = 3
            },
            new()
            {
                Id = 4, Title = "Grilled Chicken Wrap", Category = "Lunch",
                Description = "A protein-packed wrap with grilled chicken and fresh veggies.",
                Ingredients = ["1 grilled chicken breast", "1 large flour tortilla", "Lettuce and tomato", "Ranch dressing", "Shredded cheese"],
                Steps = ["Slice grilled chicken into strips.", "Warm the tortilla.", "Layer chicken, lettuce, tomato, cheese, and ranch.", "Roll tightly and slice in half."],
                TotalRatingPoints = 8, RatingCount = 2
            },
            new()
            {
                Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and savory meat sauce over perfectly cooked pasta.",
                Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g canned tomatoes", "2 tbsp tomato paste", "Olive oil", "Italian seasoning"],
                Steps = ["Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Add ground beef and brown thoroughly.", "Stir in tomatoes, tomato paste, and seasoning.", "Simmer for 20 minutes.", "Serve sauce over spaghetti with parmesan."],
                TotalRatingPoints = 28, RatingCount = 6
            },
            new()
            {
                Id = 6, Title = "Chicken Stir-Fry", Category = "Dinner",
                Description = "A quick weeknight stir-fry loaded with vegetables and savory sauce.",
                Ingredients = ["2 chicken breasts, sliced", "1 bell pepper", "1 cup broccoli", "2 tbsp soy sauce", "1 tbsp sesame oil", "Garlic and ginger", "Rice for serving"],
                Steps = ["Cook rice according to package.", "Stir-fry chicken in sesame oil until cooked.", "Add vegetables and cook 3–4 minutes.", "Add soy sauce, garlic, and ginger.", "Toss everything together.", "Serve over rice."],
                TotalRatingPoints = 17, RatingCount = 4
            },
            new()
            {
                Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Chewy, gooey chocolate chip cookies that disappear fast.",
                Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips"],
                Steps = ["Preheat oven to 375°F (190°C).", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheet.", "Bake 9–11 minutes until golden."],
                TotalRatingPoints = 30, RatingCount = 6
            },
            new()
            {
                Id = 8, Title = "Guacamole", Category = "Snacks",
                Description = "Fresh and zesty guacamole — perfect with chips or tacos.",
                Ingredients = ["3 ripe avocados", "1 lime, juiced", "½ onion, diced", "1 tomato, diced", "Cilantro", "Salt and pepper", "Jalapeño (optional)"],
                Steps = ["Mash avocados in a bowl.", "Mix in lime juice, onion, tomato, and cilantro.", "Add salt, pepper, and jalapeño to taste.", "Serve immediately with tortilla chips."],
                TotalRatingPoints = 14, RatingCount = 3
            },
            new()
            {
                Id = 9, Title = "Mango Smoothie", Category = "Drinks",
                Description = "A tropical, creamy smoothie that's ready in minutes.",
                Ingredients = ["1 cup frozen mango", "1 banana", "½ cup yogurt", "½ cup orange juice", "Honey to taste"],
                Steps = ["Add all ingredients to a blender.", "Blend until smooth.", "Pour into a glass and enjoy."],
                TotalRatingPoints = 10, RatingCount = 2
            },
        ];

        _nextId = 10;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void SubmitRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public Recipe AddRecipe(RecipeFormModel form)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = form.Title,
            Category = form.Category,
            Description = form.Description,
            Ingredients = form.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = form.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

