                Steps = ["Toast the bread until golden and crisp.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread avocado onto toast.", "Top with red pepper flakes and optional poached egg."],
                TotalRatingPoints = 18, RatingCount = 4
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Description = "A crisp and tangy classic Caesar salad with homemade dressing.",
                Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "Caesar dressing", "Lemon wedge"],
