@page "/category/{CategoryName}"
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<h1>@_category?.Icon @CategoryName Recipes</h1>
<p class="lead">@_category?.Description</p>

@if (_recipes.Count == 0)
{
    <div class="alert alert-info">
        No recipes in this category yet. <a href="submit">Be the first to submit one!</a>
    </div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in _recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">
                            <a href="recipe/@recipe.Id" class="text-decoration-none">@recipe.Title</a>
                        </h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                            }
                            <span class="text-muted ms-1">(@recipe.AverageRating / 5)</span>
                        </div>
                    </div>
                    <div class="card-footer text-muted">
                        @recipe.Ingredients.Count ingredients · @recipe.Steps.Count steps
                    </div>
                </div>
            </div>
        }
    </div>
}

<div class="mt-4">
    <a href="/" class="btn btn-outline-secondary">← Back to Categories</a>
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private RecipeCategory? _category;
